from PIL import Image
import numpy as np
from scipy.ndimage import label
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(int)
R,G,B=im.transpose(2,0,1)
tests={
'beige_bright':(R>170)&(G>160)&(B>135)&(R-B<45),
'cloth_neutral':(R>155)&(G>145)&(B>125)&(R-G<20)&(G-B<30),
'dark':im.mean(2)<45,
'wood':(R>110)&(R>G+15)&(G>B+15)&(B<130),
'orange':(R>110)&(R>G+25)&(G>B+20),
'gray':(R>80)&(abs(R-G)<12)&(abs(G-B)<12),
}
for name,m in tests.items():
 m[:65]=False
 L,n=label(m)
 comps=[]
 for i in range(1,n+1):
  yy,xx=np.where(L==i); s=len(xx)
  if s>15: comps.append((s,(xx.min(),yy.min(),xx.max(),yy.max()),tuple(np.mean(im[yy,xx],0).round().astype(int))))
 print('\\n',name,sorted(comps,reverse=True)[:20])
# detailed pixels horizontal runs passing cloth threshold
m=tests['cloth_neutral'];
for y in range(65,160,3):
 runs=[]; x=0
 while x<256:
  if m[y,x]:
   z=x
   while x<256 and m[y,x]:x+=1
   if x-z>=3:runs.append((z,x-1))
  x+=1
 if runs: print(y,runs)
PY
python3 .tmp/masks.py"

